try{const response=await fetch(@js(route('ai-content.generate')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({content_type:@js($type),topic,context,keywords,language:this.language,tone:this.tone,length:this.length})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{})[0]?.[0]||'Generation failed.');this.result=data.content}catch(e){this.error=e.message}finally{this.loading=false}},
