apply(){this.setField('title',this.result.title?this.result.title:'');this.setField('excerpt',this.result?this.result.excerpt:'');this.setField('short_description',this.result?this.result.excerpt:'');this.setField('seo_title',this.result?this.result.seo_title:'');this.setField('meta_description',this.result?this.result.meta_description:'');this.setField('tags',this.result?this.result.tags.join(', '):'');const editor=@js($type)==='product'?window.productDescriptionEditor:window.blogContentEditor;if(editor)editor.setData(this.result.description||'');else this.setField('description',this.result.description);this.result=null}}" class="ds-card ds-card-body mb-6">
